  2006  /* prefix_dt • returns dictionary definition prefix
  2007   * this is in the form of /\s{0,3}:/ (e.g. "  :", where spacing is optional) */
  2008  static size_t
  2009  prefix_dt(uint8_t *data, size_t size)
  2010  {
  2011          size_t i = 0;
  2012
  2013          /* skip up to 3 whitespaces (since it's an indented codeblock at 4) */
  2014          if (i < size && data[i] == ' ') i++;
  2015          if (i < size && data[i] == ' ') i++;
  2016          if (i < size && data[i] == ' ') i++;
