  2018          /* if the first character after whitespaces isn't :, it isn't a dt */
  2019          if (i + 1 >= size ||
  2020                  data[i] != ':' ||
  2021                  data[i + 1] != ' ')
  2022                  return 0;
  2023
  2024          if (is_next_headerline(data + i, size - i))
  2025                  return 0;
