  2035  /* prefix_dli • returns dictionary definition prefix
  2036   * a dli looks like a block of text, followed by optional whitespace, followed
  2037   * by another block with : as the first non-whitespace character */
  2038  static size_t
  2039  prefix_dli(hoedown_document *doc, uint8_t *data, size_t size)
  2040  {
  2041          /* end is to keep track of the final return value */
  2042          size_t i = 0, j = 0, end = 0;
  2043          int empty = 0;
  2044
  2045          /* if the first line has a : in front of it, it can't be a definition list
  2046           * that starts at this point */
  2047          if (prefix_dt(data, size)) {
  2048                  return 0;
  2049          }
  2050
  2051          /* temporarily toggle definition lists off to prevent infinite loops */
  2052          doc->ext_flags &= ~HOEDOWN_EXT_DEFINITION_LISTS;
  2053
  2054          /* check if it is a block of text with no double newlines inside, followed by
  2055           *  another block of text starting with : */
  2056          while (i < size) {
  2057                  /* if the line we are on is empty, flip the empty flag to indicate that
  2058                   * the next block of text we see has to start with : to be considered
  2059                   * a definition list; then skip to the next line */
  2060                  j = is_empty(data + i, size - i);
  2061                  if(j != 0) {
  2062                          empty = 1;
  2063                          i += j;
  2064                          continue;
  2065                  }
  2066
  2067                  /* if anything special is found while parsing the definition term part,
  2068                   * then return so that the main loop can deal with it */
  2069                  if (!is_paragraph(doc, data + i, size - i)) {
  2070                          break;
  2071                  }
  2072
  2073                  /* check if the current line starts with :, returning the position of the
  2074                   * beginning of the line if it does */
  2075                  j = prefix_dt(data + i, size - i);
  2076                  if (j > 0) {
  2077                          end = i;
  2078                          break;
  2079                  } else if(empty) {
  2080                          /* if an empty newline has been found, then since : was not the first
  2081                           * character after whitespaces, it can't be a definition list */
  2082                          break;
  2083                  }
  2084                  /* scan characters until the next newline */
  2085                  for (i = i + 1; i < size && data[i - 1] != '\n'; i++);
  2086          }
  2087
  2088          doc->ext_flags |= HOEDOWN_EXT_DEFINITION_LISTS;
  2089          return end;
  2090  }
